export type TournamentBackupV3RoutingExecutionsItemState = { [key: string]: unknown };

export type TournamentBackupV3RoutingExecutionsItem = {
  stageBackupId: number;
  /** @minimum 1 */
  revision: number;
  state: TournamentBackupV3RoutingExecutionsItemState;
};

export type TournamentBackupV3QualificationProposalsItemStatus = typeof TournamentBackupV3QualificationProposalsItemStatus[keyof typeof TournamentBackupV3QualificationProposalsItemStatus];


export const TournamentBackupV3QualificationProposalsItemStatus = {
  pending: 'pending',
  approved: 'approved',
} as const;

export type TournamentBackupV3QualificationProposalsItemEntriesItem = {
  basketId: string;
  playerBackupId: number;
  /** @minimum 1 */
  placementRank: number;
  /** @minimum 1 */
  basketPosition: number;
};

export type TournamentBackupV3QualificationProposalsItemOutputItem = {
  basketId: string;
  playerBackupId: number;
  /** @minimum 1 */
  finalRank: number;
};

export type TournamentBackupV3QualificationProposalsItem = {
  stageBackupId: number;
  /** @minimum 1 */
  revision: number;
  status: TournamentBackupV3QualificationProposalsItemStatus;
  /** @minLength 1 */
  rankingFingerprint: string;
  createdAt: string;
  /** @nullable */
  approvedAt: string | null;
  /** @nullable */
  approvedByActorType: string | null;
  /** @nullable */
  approvedByActorNick: string | null;
  entries: TournamentBackupV3QualificationProposalsItemEntriesItem[];
  /** Materialised output rows — present only for approved proposals. */
  output?: TournamentBackupV3QualificationProposalsItemOutputItem[];
};

export type TournamentBackupV3RouteExecutionsItemEntriesItem = {
  playerBackupId: number;
  sourceBasketId: string;
  /** @minimum 1 */
  sourceFinalRank: number;
  /** @nullable */
  sourceBasketPosition: number | null;
};

export type TournamentBackupV3RouteExecutionsItem = {
  routeId: string;
  sourceBasketId: string;
  targetBasketId: string;
  /** @minimum 1 */
  sourceProposalRevision: number;
  executedAt: string;
  actorType: string;
  actorNick: string;
  entries: TournamentBackupV3RouteExecutionsItemEntriesItem[];
};

export interface TournamentBackupV3 {
  schemaVersion: 3;
  resultModelVersion: 'series_v1';
  rankingPolicy: 'match_record_v1';
  exportedAt: string;
  tournament: TournamentBackupV3Tournament;
  players: TournamentBackupV3PlayersItem[];
  /**
     * @minItems 1
     * @maxItems 10
     */
  stages: TournamentBackupV3StagesItem[];
  groups: TournamentBackupV3GroupsItem[];
  stageParticipants: TournamentBackupV3StageParticipantsItem[];
  /** Optional persisted internal runtime for Marvel elimination-group stages. */
  marvelRounds?: TournamentBackupV3MarvelRoundsItem[];
  marvelGroups?: TournamentBackupV3MarvelGroupsItem[];
  marvelGroupEntries?: TournamentBackupV3MarvelGroupEntriesItem[];
  /** Optional explicit stage basket configuration. Its absence preserves legacy one-input/one-output semantics. */
  stageBaskets?: TournamentBackupV3StageBasketsItem[];
  /** Optional routes between explicit output and input baskets. */
  stageBasketRoutes?: TournamentBackupV3StageBasketRoutesItem[];
  matches: TournamentBackupV3MatchesItem[];
  resultHistory: TournamentBackupV3ResultHistoryItem[];
  actionLog: TournamentBackupV3ActionLogItem[];
  /** Per-player Deadlock hero bans (optional, present only for Deadlock tournaments) */
  deadlockBans?: TournamentBackupV3DeadlockBansItem[];
  /** Per-game hero picks for each match (optional, present only when picks exist) */
  gamePicks?: TournamentBackupV3GamePicksItem[];
  /**
     * Optional sealed Tournament Engine V2 routing plan. Required for Double Elimination backups.
     * @nullable
     */
  routingPlan?: TournamentBackupV3RoutingPlan;
  /** Mutable Tournament Engine V2 stage snapshots, keyed by the backed-up stage. */
  routingExecutions?: TournamentBackupV3RoutingExecutionsItem[];
  /** Qualification proposals (one per stage). Present only when the organiser has generated at least one proposal. */
  qualificationProposals?: TournamentBackupV3QualificationProposalsItem[];
  /** Materialised basket route executions. Present only when at least one route has been executed. */
  routeExecutions?: TournamentBackupV3RouteExecutionsItem[];
}

export type BasketRouteExecutionEntriesItem = {
  playerId: number;
  /** @minimum 1 */
  sourceFinalRank: number;
  /** @nullable */
  sourceBasketPosition: number | null;
  sourceOutputPlayerId: number;
};

export interface BasketRouteExecution {
  executionId: number;
  tournamentId: number;
  routeId: string;
  sourceStageId: number;
  sourceBasketId: string;
  targetStageId: number;
  targetBasketId: string;
  sourceProposalId: number;
  /** @minimum 1 */
  sourceProposalRevision: number;
  executedAt: string;
  actorType: string;
  actorNick: string;
  /** @minimum 0 */
  routedPlayerCount: number;
  entries: BasketRouteExecutionEntriesItem[];
}

export interface BasketRouteStatus {
  routeId: string;
  tournamentId: number;
  sourceStageId: number;
  sourceBasketId: string;
  targetStageId: number;
  targetBasketId: string;
  sourceOutputApproved: boolean;
  materialized: boolean;
  /** @minimum 0 */
  routedPlayerCount: number;
  execution: BasketRouteExecution | null;
}

export type TargetStageInputArrivalsBasketsItemDirectPlayersItem = {
  playerId: number;
};

export type TargetStageInputArrivalsBasketsItemRoutedArrivalsItem = {
  playerId: number;
  /** @minimum 1 */
  sourceFinalRank: number;
  /** @nullable */
  sourceBasketPosition: number | null;
  sourceStageId: number;
  sourceBasketId: string;
  routeId: string;
  sourceProposalId: number;
  executionId: number;
  arrivedAt: string;
};

export type TargetStageInputArrivalsBasketsItem = {
  basketId: string;
  /** @minimum 0 */
  directCount: number;
  /** @minimum 0 */
  routedCount: number;
  /** @minimum 0 */
  totalCount: number;
  directPlayers: TargetStageInputArrivalsBasketsItemDirectPlayersItem[];
  routedArrivals: TargetStageInputArrivalsBasketsItemRoutedArrivalsItem[];
};

export interface TargetStageInputArrivals {
  targetStageId: number;
  /** @minimum 0 */
  totalDirectCount: number;
  /** @minimum 0 */
  totalRoutedCount: number;
  /** @minimum 0 */
  totalCount: number;
  baskets: TargetStageInputArrivalsBasketsItem[];
}

export type TournamentBackup = TournamentBackupV2 | TournamentBackupV3;

export interface BackupRestoreInput {
  backup: TournamentBackup;
  /**
     * New organizer password. Credentials are never read from the backup.
     * @minLength 8
     */
  organizerPassword: string;
  /**
     * New viewer password, required when the restored tournament is private_online.
     * @minLength 8
     */
  viewerPassword?: string;
  /**
     * Optional new support password. When omitted, support access remains disabled.
     * @minLength 8
     */
  supportPassword?: string;
}

export interface ImportResult {
  tournament: Tournament;
  playersImported: number;
  matchesImported: number;
  /** Organizer token scoped to the newly restored tournament. */
  organizerToken: string;
}

export type TournamentStatsTopPlayersItem = {
  id?: number;
  name?: string;
  matchWins?: number;
  matchLosses?: number;
  gameDiff?: number;
};

export interface TournamentStats {
  totalPlayers: number;
  totalMatches: number;
  completedMatches: number;
  pendingMatches: number;
  inProgressMatches?: number;
  /** @nullable */
  currentRound: number | null;
  /** @nullable */
  totalRounds?: number | null;
  topPlayers?: TournamentStatsTopPlayersItem[];
}

export type UndoLastAction404 = {
  error?: string;
};

